// Question bank.
//
// Every question has four options. The correct option is the one at index `answer`
// (0 when omitted); the app shuffles options unless `ordered` is true. The wrong options
// are deliberately the mistakes students actually make, and the explanation names the
// rule that was broken.
//
// Text may mix Hebrew and math. Math goes between $...$ and is written in KaTeX/LaTeX.
// Strings use String.raw (the `r` tag) so backslashes are written once.
//
// Fields:
//   id          unique, stable id
//   level       1 = יסודות, 2 = 3 יח״ל, 3 = 4 יח״ל, 4 = 5 יח״ל (see LEVELS in quiz.js)
//   topic       key from TOPICS in quiz.js
//   type        'value'     למה שווה / מה הפתרון
//               'step'      איזה מעבר נכון
//               'error'     איפה הטעות (uses `steps`, options name the lines, `ordered`)
//               'condition' מתי החוק נכון
//   prompt      the question
//   steps       (error only) the lines of a worked solution, numbered by the app
//   options     four answers
//   answer      index of the correct option, default 0
//   ordered     keep options in the written order
//   explanation shown after answering
